function currentTasks(){if(flowWorkspace?.stageTasks&&flowWorkspace.phase===phase&&flowWorkspace.sub===sub)return flowWorkspace.stageTasks.map(t=>t.name);const names=phase==='研发'?(developmentTaskExamples[sub]||[]).map(t=>t.name):taskSets[phase];return flowWorkspace&&flowWorkspace.phase===phase&&flowWorkspace.sub===sub&&!names.includes(flowWorkspace.node.name)?[...names,flowWorkspace.node.name]:names}
