function taskState(p,t){if(p==='项目立项'&&t==='技术调研')return technicalComplete?'已完成':'进行中';const entry=flowWorkspace?.phase===p&&flowWorkspace.sub===sub?flowWorkspace.stageTasks?.find(n=>n.name===t):null;if(entry)return flowSummary?.tasks?.[p+'/'+entry.id]?.status||entry.status;if(flowWorkspace&&flowWorkspace.phase===p&&flowWorkspace.sub===sub&&flowWorkspace.node.name===t)return flowWorkspace.status;if(p==='市场分析'||p==='项目立项')return '已完成';if(p==='研发'&&sub==='实施条件验证')return '已完成';if(p==='研发'&&sub==='路线筛选'){if(t==='计算模拟')return state.stageTaskComplete?'已完成':'进行中';if(t==='建立批料与施工窗证据'&&state.stageTaskComplete)return '进行中';}return '待开始'}
