 all('[data-phase]').forEach(b=>{const p=b.dataset.phase,status=flowSummary?.phaseStatuses?.[p]||(['市场分析','项目立项'].includes(p)?'已完成':p==='研发'?'进行中':'待开始');b.querySelector('.phase-copy small').innerHTML=stateIcon(status)+status;b.dataset.progress=status;b.setAttribute('aria-label',p+'，'+status);b.classList.toggle('project-in-progress',status==='进行中');b.querySelector('.project-current-marker')?.remove()});
