const completionDialog=document.createElement('dialog');completionDialog.className='completion-dialog';completionDialog.setAttribute('aria-labelledby','completion-title');completionDialog.innerHTML='<h2 id="completion-title">完成技术调研任务？</h2><p id="completion-description"></p><p class="research-muted">确认后任务状态变为已完成，待办、材料编辑及 Copilot 操作将锁定。立项评审进入进行中。</p><div class="completion-actions"><button class="btn" data-cancel-completion>继续检查</button><button class="btn primary" data-confirm-completion>确认完成</button></div>';document.body.append(completionDialog);
